/* The tool's own manifest, read once: status, id and benchmark tally. */
let MANI;
function manifest(){
 if(MANI!==undefined)return MANI;
 MANI=null;
 try{const el=document.getElementById('diagram-tool-manifest');if(el)MANI=JSON.parse(el.textContent)}catch(e){MANI=null}
 return MANI;
}
function statusInfo(){
 const m=manifest()||{};
 const v=(m.validation&&typeof m.validation==='object')?m.validation:{};
 const bs=Array.isArray(v.benchmarks)?v.benchmarks:[];
 const r=v.review;
 const reviewed=!!((r&&typeof r==='object'&&Object.keys(r).length>0)||(typeof r==='string'&&r.trim()!==''));
 let st=m.status==='benchmarked'||m.status==='verified'?'benchmarked':'prototype';
 if(m.status==='verified'&&reviewed)st='verified';
 else if(v.benchmark_status==='partial')st='partial';
 let cases=0,passed=0;
 bs.forEach(b=>{cases+=(+b.cases||0);passed+=(+b.passed||0)});
 const bd=(v.benchmark_display&&typeof v.benchmark_display==='object')?v.benchmark_display:null;
 if(bd&&Number.isFinite(+bd.cases)&&Number.isFinite(+bd.passed)&&+bd.cases>0){cases=+bd.cases;passed=+bd.passed}
 return {status:st,id:m.id||filename.replace(/\.html?$/,''),cases:cases,passed:passed,
         report:bs.some(b=>b&&b.artifact)};
}
function baseLang(v){return String(v||'').toLowerCase().split('-')[0]}
function currentLang(){
  try{const q=baseLang(new URLSearchParams(location.search).get('lang'));if(supported.includes(q))return q}catch(e){}
  const h=baseLang(document.documentElement.lang);if(supported.includes(h))return h;
  try{const s=baseLang(localStorage.getItem('diagram_lang'));if(supported.includes(s))return s}catch(e){}
  const n=(navigator.languages&&navigator.languages[0])||navigator.language;const b=baseLang(n);return supported.includes(b)?b:'en';
}
function t(key,lang){const d=DATA.ui[key]||{};return d[lang]||d.en||''}
function toolData(){return DATA.tools[filename]||null}
function toolLimit(lang){const x=toolData();return x?(x[1][lang]||x[1].en):t('short',lang)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
